def solve(grid):
    """Count the number of islands (connected components of 1s) in a 2D grid.
    Connections are 4-directional (up, down, left, right).
    Args:
        grid (List[List[int]]): matrix of 0s and 1s.
    Returns:
        int: number of islands.
    """
    if not grid:
        return 0
    m, n = len(grid), len(grid[0])
    visited = [[False] * n for _ in range(m)]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if visited[i][j]:
                continue
            visited[i][j] = True
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni, nj = i+di, j+dj
                if 0 <= ni < m and 0 <= nj < n and not visited[ni][nj] and grid[ni][nj] == 1:
                    stack.append((ni, nj))
    count = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1 and not visited[i][j]:
                count += 1
                dfs(i, j)
    return count

