    if not grid:
        return 0
    m = len(grid)
    # Maximum row length determines column dimension for visited matrix.
    n = max((len(row) for row in grid), default=0)
    if n == 0:
        return 0
    visited = [[False] * n for _ in range(m)]
    def is_land(i, j):
        # A cell is land if it exists and its value is non-zero.
        return j < len(grid[i]) and grid[i][j] != 0
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny] and is_land(nx, ny):
                    stack.append((nx, ny))
    count = 0
    for i in range(m):
        for j in range(len(grid[i])):
            if is_land(i, j) and not visited[i][j]:
                count += 1
                dfs(i, j)
    return count

