def solve(intervals):
    # Normalize intervals and handle empty input
    if not intervals:
        return []
    # Ensure each interval is a pair of numbers and ordered (start <= end)
    norm = []
    for iv in intervals:
        if not iv:
            continue  # skip empty sublists just in case
        a, b = iv[0], iv[1]
        if a > b:
            a, b = b, a
        norm.append([a, b])
    if not norm:
        return []
    # Sort by start
    norm.sort(key=lambda x: x[0])
    merged = []
    cur_start, cur_end = norm[0]
    for start, end in norm[1:]:
        # Overlap or touch (start <= cur_end)
        if start <= cur_end:
            cur_end = max(cur_end, end)
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = start, end
    merged.append([cur_start, cur_end])
    return merged

