def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    Supports +, -, *, / where division truncates toward zero.
    Returns 0 for empty input or division by zero (defensive)."""
    stack = []
    for t in tokens:
        if t in ('+', '-', '*', '/'):
            # Pop two operands; if insufficient, treat missing as 0
            b = stack.pop() if stack else 0
            a = stack.pop() if stack else 0
            if t == '+':
                res = a + b
            elif t == '-':
                res = a - b
            elif t == '*':
                res = a * b
            else:  # division
                if b == 0:
                    # undefined, return 0 per defensive spec
                    res = 0
                else:
                    # Truncate toward zero without using float
                    sign = -1 if (a * b) < 0 else 1
                    res = sign * (abs(a) // abs(b))
            stack.append(res)
        else:
            # Assume token is an integer in string form
            try:
                stack.append(int(t))
            except Exception:
                # Non‑numeric token, treat as 0
                stack.append(0)
    return stack[0] if stack else 0

