def solve(tokens):
    """Evaluate Reverse Polish Notation.
    Tokens may be strings or integers representing numbers, and the operators '+', '-', '*', '/'.
    Division truncates toward zero.
    Returns integer result.
    """
    stack = []
    ops = {'+', '-', '*', '/'}
    for tok in tokens:
        # Determine if token is an operator
        if tok in ops:
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # division, truncate toward zero
                res = int(a / b)
            stack.append(res)
        else:
            # Token is a number (string or int)
            if isinstance(tok, int):
                stack.append(tok)
            else:
                stack.append(int(tok))
    return stack[0] if stack else 0

